from collections import Counter

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = Counter(x for row in g for x in row).most_common(1)[0][0]

    def runs(line):
        out, i = [], 0
        while i < len(line):
            if line[i] == bg:
                i += 1
                continue
            color, start = line[i], i
            while i < len(line) and line[i] == color:
                i += 1
            if i - start >= 2:
                out.append((color, start, i))
        return out

    # Matching bars on left/right borders: dots within one bar determine
    # horizontal rays and the same offset pattern across the opposite bar.
    lr = runs([g[r][0] for r in range(h)])
    rr = runs([g[r][w-1] for r in range(h)])
    for color, a, b in lr:
        for color2, c, d in rr:
            if color != color2 or b-a != d-c:
                continue
            for source, target, from_left in (( (a,b),(c,d),True), ((c,d),(a,b),False)):
                s, e = source
                marks = [(r,x) for r in range(s,e) for x in range(1,w-1)
                         if g[r][x] not in (bg,color)]
                if not marks:
                    continue
                ink = Counter(g[r][x] for r,x in marks).most_common(1)[0][0]
                marks = [(r,x) for r,x in marks if g[r][x] == ink]
                offsets = set()
                for r,x in marks:
                    offsets.add(r-s)
                    if from_left:
                        for q in range(1,x):
                            if g[r][q] == bg: g[r][q] = ink
                    else:
                        for q in range(x+1,w-1):
                            if g[r][q] == bg: g[r][q] = ink
                    g[r][x] = 4
                t, u = target
                for off in offsets:
                    row = t + off
                    if row >= u: continue
                    cols = range(0,w-1) if from_left else range(1,w)
                    for q in cols:
                        if g[row][q] == bg: g[row][q] = ink
                return g

    # Matching bars on top/bottom borders send rays along the inward axis.
    top = runs(g[0])
    bottom = runs(g[h-1])
    for color, a, b in top:
        for color2, c, d in bottom:
            if color != color2:
                continue
            candidates = Counter(g[r][x] for r in range(1,h-1) for x in range(w)
                                 if g[r][x] not in (bg,color))
            if not candidates:
                continue
            ink = candidates.most_common(1)[0][0]
            for start, end, down in ((a,b,True),(c,d,False)):
                col = end - 1
                rows = range(1,h) if down else range(h-2,-1,-1)
                for r in rows:
                    if g[r][col] == ink:
                        g[r][col] = 4
                        break
                    if g[r][col] == bg:
                        g[r][col] = ink
                    else:
                        break
            return g
    return g

